// ---- Games List ----

/**
 * Right-hand badge on a phase header.
 *
 * Promotion shows the candidate's score against the champion and the gate
 * verdict; eval shows the win rate against the random bot. The percentage is
 * derived from the same games listed underneath so the two always agree.
 */
function gamesPhaseBadge(phase) {
    const color = (rate, threshold = 0.5) => {
        if (rate > threshold) return 'var(--success)';
        if (rate < threshold) return 'var(--danger)';
        return 'var(--warning)';
    };

    if (phase.phase === 'promotion') {
        const rate = phase.candidate_win_rate !== undefined && phase.candidate_win_rate !== null
            ? phase.candidate_win_rate
            : phase.gate_win_rate;
        if (rate === undefined || rate === null) return '';

        const tally = phase.candidate_wins !== undefined ? ` (${phase.candidate_wins}/${phase.count})` : '';
        const verdict = phase.promoted === true
            ? '<span style="color: var(--success);">✅</span>'
            : (phase.promoted === false ? '<span style="color: var(--danger);">⛔</span>' : '');
        return `<span class="group-note">${verdict}
            <span style="color: ${color(rate, phase.gate_threshold || 0.5)}; font-weight: 600;">
                Cand WR: ${Math.round(rate * 100)}%${tally}
            </span>
        </span>`;
    }

    if (phase.phase === 'eval' && phase.win_rate !== null && phase.win_rate !== undefined) {
        return `<span class="group-note" style="color: ${color(phase.win_rate)}; font-weight: 600;">
            WR: ${Math.round(phase.win_rate * 100)}% (${phase.ai_wins}/${phase.rated_games})
        </span>`;
    }

    return '';
}

